def f_normpath(p):
    parts = p.split('/')
    stack = []
    for part in parts:
        if part == '.':
            continue
        if part == '..':
            if stack or (not p.startswith('/') and stack):
                stack.pop()
        elif part:
            stack.append(part)
    return '/' + '/'.join(stack) if stack or p.startswith('/') else '.'
