def f_b32(b: bytes) -> str:
    if not b:
        return ""
    base32_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
    padded = b.ljust((len(b) + 4) // 5 * 5, b'\x00')
    encoded = padded.hex().upper().rjust((len(padded) + 1) // 2, '0')
    result = []
    for i in range(0, len(encoded), 10):
        chunk = encoded[i:i+10]
        result.append(base32_chars[int(chunk[:8], 16)] + base32_chars[int(chunk[8:], 16)])
    return ''.join(result).ljust(len(result) * 8 // 5, '=')
```

